package com.example.lending;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import static org.hamcrest.Matchers.containsInAnyOrder;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class BookSearchIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Test
    void matches_title_substring_ignoring_case() throws Exception {
        registerBook("Hyperion Spring in Action");
        registerBook("hyperion SPRING Boot Cookbook");
        registerBook("Hyperion Effective Java");

        mockMvc.perform(get("/books").param("title", "spring"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[*].title", containsInAnyOrder(
                        "Hyperion Spring in Action", "hyperion SPRING Boot Cookbook")))
                .andExpect(jsonPath("$[0].status").value("AVAILABLE"));
    }

    @Test
    void percent_and_underscore_in_the_query_are_matched_literally() throws Exception {
        registerBook("Coverage 100% Report");
        registerBook("Coverage 1000 Pages");

        mockMvc.perform(get("/books").param("title", "100%"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$[*].title", containsInAnyOrder("Coverage 100% Report")));
    }

    @Test
    void no_match_returns_an_empty_list() throws Exception {
        mockMvc.perform(get("/books").param("title", "no-such-title-zzq"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$").isEmpty());
    }

    @Test
    void blank_title_returns_400() throws Exception {
        mockMvc.perform(get("/books").param("title", "   "))
                .andExpect(status().isBadRequest());
    }

    @Test
    void missing_title_returns_400() throws Exception {
        mockMvc.perform(get("/books"))
                .andExpect(status().isBadRequest());
    }

    private void registerBook(String title) throws Exception {
        mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"" + title + "\"}"))
                .andExpect(status().isCreated());
    }
}
